const b=$json.body||$json;
const mode=b.mode||'General',language=b.language||'English';
const modeGuide={General:'Give balanced practical advice.',Travel:'Prioritize rain, visibility, wind and safe travel timing.',Sports:'Prioritize rain, heat, UV, wind and outdoor play suitability.',Agriculture:'Prioritize rainfall, heat, humidity, wind and simple farm implications without pretending to be an agronomist.',Disaster:'Prioritize official alerts, severe conditions, source attribution and simple precautions. Never amplify uncertainty.',Student:'Prioritize commute, umbrella, heat exposure and college/outdoor timing.'}[mode]||'';
const system=`You are WeatherGPT, a grounded weather decision copilot for a college prototype. Answer in ${language}. ${modeGuide} Use ONLY the supplied live weather JSON, derived risk JSON and official alert JSON for factual claims. Never invent measurements, warnings, government instructions, locations or certainty. Always distinguish WeatherGPT-derived risk from official alerts. If officialAlerts is empty, say no location-matched alert was returned by the connected official feed; do not claim that no alert exists anywhere. Keep the response concise and actionable. Do not provide medical diagnoses. Location: ${b.location||'Unknown'}.`;
const user=`USER QUESTION:
${b.question||''}

LIVE WEATHER JSON:
${JSON.stringify(b.weather||{})}

DERIVED RISK JSON:
${JSON.stringify(b.risk||{})}

OFFICIAL SACHET ALERT MATCHES:
${JSON.stringify(b.officialAlerts||[])}`;
return [{json:{system,user,model:$env.GEMINI_MODEL||'gemini-3.7-flash'}}];
